svg.script:
(function () {
  var svg = document.getElementById('svg1') || document.querySelector('svg');
  var tooltip = document.getElementById('region-tooltip');
  var tooltipBg = document.getElementById('region-tooltip-bg');
  var tooltipText = document.getElementById('region-tooltip-text');
  var regions = document.querySelectorAll('path.region');
  var pad = 1;

  function toSvgPoint(evt) {
    var pt = svg.createSVGPoint();
    pt.x = evt.clientX;
    pt.y = evt.clientY;
    var ctm = svg.getScreenCTM();
    return ctm ? pt.matrixTransform(ctm.inverse()) : pt;
  }

  function positionTooltip(p) {
    tooltip.setAttribute('transform', 'translate(' + (p.x + 2) + ',' + (p.y - 2) + ')');
  }

  function showTooltip(evt, name) {
    tooltipText.textContent = name;
    var bbox = tooltipText.getBBox();
    tooltipBg.setAttribute('x', bbox.x - pad);
    tooltipBg.setAttribute('y', bbox.y - pad);
    tooltipBg.setAttribute('width', bbox.width + pad * 2);
    tooltipBg.setAttribute('height', bbox.height + pad * 2);
    tooltip.classList.add('visible');
    svg.appendChild(tooltip);
    positionTooltip(toSvgPoint(evt));
  }

  regions.forEach(function (region) {
    var name = (region.getAttribute('name') || '').trim();
    region.addEventListener('mouseenter', function (evt) {
      showTooltip(evt, name);
    });
    region.addEventListener('mousemove', function (evt) {
      positionTooltip(toSvgPoint(evt));
    });
    region.addEventListener('mouseleave', function () {
      tooltip.classList.remove('visible');
    });
  });
})();
